const makeEx=(name,group='Własne',gear='Inne',sets=3,reps=10,kg=0)=>({id:uid(),name,group,gear,sets:Array.from({length:sets},()=>({reps,kg,done:false}))});
const defaults=[{id:'a',name:'Siła A',focus:'Całe ciało',minutes:40,ex:[makeEx('Przysiad z hantlem','Nogi','Hantle',3,10,5),makeEx('Wiosłowanie hantlami','Plecy','Hantle',3,10,5),makeEx('Wyciskanie hantli leżąc','Klatka','Hantle',3,10,5),makeEx('Monster walk','Pośladki','Taśma',3,12,0),makeEx('Dead bug','Core','Masa ciała',3,8,0)]},{id:'b',name:'Siła B',focus:'Pośladki · plecy · core',minutes:42,ex:[makeEx('Martwy ciąg z hantlami','Pośladki','Hantle',3,10,5),makeEx('Glute bridge z taśmą','Pośladki','Taśma',3,12,5),makeEx('Wyciskanie nad głowę','Barki','Hantle',3,8,5),makeEx('Ściąganie taśmy do klatki','Plecy','Taśma',3,12,0),makeEx('Bird dog','Core','Masa ciała',3,8,0)]},{id:'c',name:'Kondycja + mobilność',focus:'Lżejsza sesja',minutes:30,ex:[makeEx('Marsz z wysokim unoszeniem kolan','Kondycja','Masa ciała',4,20,0),makeEx('Przysiad do krzesła','Nogi','Masa ciała',3,12,0),makeEx('Pallof press','Core','Taśma',3,10,0),makeEx('Mobilizacja bioder','Mobilność','Mata',1,8,0)]}];
const oldPlans=JSON.parse(localStorage.getItem('hwt-plans')||'null');function migratePlan(p){return {...p,ex:(p.ex||[]).map(e=>e.sets instanceof Array?e:makeEx(e.name,e.group,e.gear,Number(e.sets)||3,parseInt(e.reps)||10,Number(e.kg)||0))}}
let plans=(oldPlans?oldPlans.map(migratePlan):defaults),logs=(JSON.parse(localStorage.getItem('hwt-v2-logs')||'null')||JSON.parse(localStorage.getItem('hwt-logs')||'[]')).map(l=>({...l,ex:(l.ex||[]).map(e=>e.sets instanceof Array?e:makeEx(e.name,e.group,e.gear,Number(e.sets)||3,parseInt(e.reps)||10,Number(e.kg)||0))})),weights=JSON.parse(localStorage.getItem('hwt-weights')||'[]'),tab='home',active=null,started=0,timerId=null,view=null,pickerFor=null,editing=null,filters={q:'',group:'Wszystkie',gear:'Wszystkie'};
const app=document.querySelector('#app');document.querySelector('#nav').innerHTML=`<button data-tab="home">⌂<span>Start</span></button><button data-tab="plans">▦<span>Plany</span></button><button data-tab="history">◷<span>Historia</span></button><button data-tab="stats">⌁<span>Postępy</span></button>`;
let save=()=>{localStorage.setItem('hwt-plans',JSON.stringify(plans));localStorage.setItem('hwt-v2-logs',JSON.stringify(logs));localStorage.setItem('hwt-weights',JSON.stringify(weights))};
function render(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));({home:home,plans:planPage,history:historyPage,stats:statsPage}[tab]||home)();bind()}
function page(title,kicker,content,action=''){app.innerHTML=`<section><div class="page-head"><div><label>${kicker}</label><h1>${title}</h1></div>${action}</div>${content}</section>`}
function heatmap(){const days=84,done=new Set(logs.map(l=>new Date(l.date).toISOString().slice(0,10)));return `<div class="heatmap">${Array.from({length:days},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(days-1-i));return `<i class="${done.has(d.toISOString().slice(0,10))?'hit':''}" title="${d.toLocaleDateString('pl')}"></i>`}).join('')}</div>`}
function home(){const week=recent(7).length,vol=recent(7).reduce((a,l)=>a+volume(l),0),last=logs[0],streak=getStreak();page('Cześć!','TWÓJ DASHBOARD',`<div class="hero-card"><div><small>AKTYWNOŚĆ · 12 TYGODNI</small><h2>${logs.length?`${logs.length} wykonanych treningów`:'Zacznij budować regularność'}</h2></div><span class="streak">${streak} <small>dni serii</small></span>${heatmap()}</div><div class="kpis"><article><small>TEN TYDZIEŃ</small><strong>${week}<em>/ 3</em></strong><span>treningi</span></article><article><small>OBJĘTOŚĆ</small><strong>${Math.round(vol)}<em> kg</em></strong><span>w ostatnich 7 dniach</span></article><article><small>OSTATNI TRENING</small><strong class="text">${last?esc(last.name):'—'}</strong><span>${last?new Date(last.date).toLocaleDateString('pl'):'brak danych'}</span></article></div><div class="section-title"><div><small>NA DZIŚ</small><h2>Wybierz trening</h2></div><button id="quick">＋ Pusty trening</button></div><div class="programs">${plans.slice(0,3).map((p,i)=>`<article class="program c${i}"><span>0${i+1}</span><div><h3>${esc(p.name)}</h3><p>${esc(p.focus)} · ${p.ex.length} ćwiczeń</p></div><button class="begin" data-id="${p.id}">Start</button></article>`).join('')}</div><div class="weight-card"><div><small>MASA CIAŁA</small><h2>${weights[0]?weights[0].value+' kg':'Dodaj pierwszy pomiar'}</h2><p>${weights.length>1?delta(weights[0].value-weights[1].value)+' kg od poprzedniego pomiaru':'Śledź zmianę w czasie'}</p></div><button id="add-weight">＋ Pomiar</button></div>`)}
function planPage(){page('Twoje plany','TRENINGI',`<p class="lead">Gotowe zestawy możesz dowolnie edytować. Ćwiczenia dodajesz z biblioteki lub tworzysz własne.</p><div class="plan-grid">${plans.map((p,i)=>`<article class="plan-card c${i%3}"><div class="plan-top"><span>0${i+1}</span><button class="edit-plan" data-id="${p.id}">•••</button></div><h2>${esc(p.name)}</h2><p>${esc(p.focus)}</p><ul>${p.ex.slice(0,4).map(e=>`<li>${esc(e.name)} <small>${e.sets.length} serie</small></li>`).join('')}</ul><div><button class="begin primary" data-id="${p.id}">Rozpocznij</button><button class="edit-plan outline" data-id="${p.id}">Edytuj</button></div></article>`).join('')}</div>${editing?editor():''}`,`<button id="new-plan" class="head-action">＋ Nowy plan</button>`)}
function editor(){return `<div class="overlay"><div class="modal"><div class="modal-head"><div><small>EDYTOR PLANU</small><h2>${esc(editing.name)}</h2></div><button class="close">×</button></div><div class="meta"><label>Nazwa<input id="pn" value="${esc(editing.name)}"></label><label>Opis<input id="pf" value="${esc(editing.focus)}"></label></div><div class="edit-ex">${editing.ex.map((e,i)=>`<article><i>${i+1}</i><div><b>${esc(e.name)}</b><small>${e.group} · ${e.gear}</small></div><label>serie<input class="plan-sets" data-i="${i}" type="number" value="${e.sets.length}" min="1" max="10"></label><button class="drop-ex" data-i="${i}">×</button></article>`).join('')}</div><button id="pick-ex" class="library-button">＋ Dodaj z biblioteki ćwiczeń</button><div class="modal-actions"><button class="close ghost">Anuluj</button><button id="save-plan" class="primary">Zapisz plan</button></div></div></div>${pickerFor==='plan'?picker():''}`}
function picker(){const groups=['Wszystkie',...new Set(LIB.map(e=>e.group))],gears=['Wszystkie',...new Set(LIB.map(e=>e.gear))],list=LIB.filter(e=>(filters.group==='Wszystkie'||e.group===filters.group)&&(filters.gear==='Wszystkie'||e.gear===filters.gear)&&e.name.toLowerCase().includes(filters.q.toLowerCase()));return `<div class="overlay picker-layer"><div class="modal picker"><div class="modal-head"><div><small>BIBLIOTEKA</small><h2>Wybierz ćwiczenie</h2></div><button id="close-picker">×</button></div><div class="search"><input id="search-ex" placeholder="Szukaj ćwiczenia…" value="${esc(filters.q)}"><button id="custom-ex">＋ Własne</button></div><div class="chips">${groups.map(g=>`<button class="group-chip ${filters.group===g?'on':''}" data-v="${g}">${g}</button>`).join('')}</div><select id="gear-filter">${gears.map(g=>`<option ${filters.gear===g?'selected':''}>${g}</option>`).join('')}</select><div class="library-list">${list.map(e=>`<button class="choose-ex" data-id="${e.id}"><i>${muscleIcon(e.group)}</i><span><b>${esc(e.name)}</b><small>${e.group} · ${e.gear}</small></span><em>＋</em></button>`).join('')||'<p class="empty-line">Brak wyników. Dodaj własne ćwiczenie.</p>'}</div></div></div>`}
function startWorkout(p){active=structuredClone(p);active.ex.forEach(e=>e.sets.forEach(s=>s.done=false));started=Date.now();view='workout';tab='home';timerId&&clearInterval(timerId);timerId=setInterval(()=>{const el=document.querySelector('#timer');if(el)el.textContent=time(Date.now()-started)},1000);render()}
function workout(){const total=active.ex.reduce((a,e)=>a+e.sets.length,0),done=active.ex.reduce((a,e)=>a+e.sets.filter(s=>s.done).length,0);app.innerHTML=`<section class="workout"><div class="workout-bar"><button id="quit">×</button><div><small>AKTYWNY TRENING</small><strong id="timer">${time(Date.now()-started)}</strong></div><span>${done}/${total}</span><button id="finish-workout">✓</button></div><h1>${esc(active.name)}</h1><p>${esc(active.focus)}</p><div class="active-list">${active.ex.map((e,ei)=>exerciseCard(e,ei)).join('')}</div><button id="add-active-ex" class="library-button">＋ Dodaj ćwiczenie</button></section>${pickerFor==='active'?picker():''}`;bindWorkout()}
function exerciseCard(e,ei){const prev=previous(e.name);return `<article class="active-card"><div class="active-title"><i>${muscleIcon(e.group)}</i><div><h2>${esc(e.name)}</h2><small>${prev?`Poprzednio: ${prev}`:`${e.group} · ${e.gear}`}</small></div><button class="remove-active" data-e="${ei}">•••</button></div><div class="set-head"><span>SERIA</span><span>KG</span><span>POWT.</span><span>RPE</span><span>✓</span></div>${e.sets.map((s,si)=>`<div class="set-row ${s.done?'done':''}"><b>${si+1}</b><input data-e="${ei}" data-s="${si}" data-f="kg" type="number" inputmode="decimal" value="${s.kg}"><input data-e="${ei}" data-s="${si}" data-f="reps" type="number" inputmode="numeric" value="${s.reps}"><input data-e="${ei}" data-s="${si}" data-f="rpe" type="number" inputmode="decimal" placeholder="–" value="${s.rpe}"><button class="toggle-set" data-e="${ei}" data-s="${si}">${s.done?'✓':'○'}</button></div>`).join('')}<button class="add-set" data-e="${ei}">＋ Dodaj serię</button></article>`}
function finishPage(){const ms=Date.now()-started;app.innerHTML=`<section class="finish-page"><div class="success">✓</div><label>TRENING ZAKOŃCZONY</label><h1>Dobra robota!</h1><div class="summary-kpis"><div><small>CZAS</small><strong>${time(ms)}</strong></div><div><small>SERIE</small><strong>${active.ex.reduce((a,e)=>a+e.sets.filter(s=>s.done).length,0)}</strong></div><div><small>OBJĘTOŚĆ</small><strong>${volume({ex:active.ex})} kg</strong></div></div><div class="finish-form"><label>Spalone kalorie<input id="fkcal" type="number" placeholder="0"><span>kcal</span></label><label>Średnie tętno<input id="fbpm" type="number" placeholder="0"><span>bpm</span></label><label>Jak było?<select id="ffeel"><option>Świetnie</option><option selected>W porządku</option><option>Ciężko</option><option>Bardzo ciężko</option></select></label></div><button id="save-workout" class="primary wide">Zapisz trening</button><button id="back-workout" class="ghost">Wróć do treningu</button></section>`;bindFinish()}
function historyPage(){if(view?.startsWith('log:'))return logDetail(view.split(':')[1]);page('Historia','TWOJE SESJE',logs.length?`<div class="log-list">${logs.map(l=>`<button class="log" data-id="${l.id}"><div class="date"><strong>${new Date(l.date).getDate()}</strong><span>${new Date(l.date).toLocaleDateString('pl',{month:'short'})}</span></div><div><h2>${esc(l.name)}</h2><p>${l.ex.length} ćwiczeń · ${l.minutes||0} min</p><small>${volume(l)} kg objętości　${l.kcal||'—'} kcal　${l.bpm||'—'} bpm</small></div><em>›</em></button>`).join('')}</div>`:`<div class="empty"><i>◷</i><h2>Brak zapisanych sesji</h2><p>Wykonany trening pojawi się tutaj.</p><button data-tab="home" class="primary">Wybierz trening</button></div>`)}
function logDetail(id){const l=logs.find(x=>x.id===id);if(!l){view=null;return historyPage()}app.innerHTML=`<section><button id="back-history" class="back">← Historia</button><label>${new Date(l.date).toLocaleDateString('pl',{weekday:'long',day:'numeric',month:'long'})}</label><h1>${esc(l.name)}</h1><div class="summary-kpis"><div><small>CZAS</small><strong>${l.minutes||0} min</strong></div><div><small>OBJĘTOŚĆ</small><strong>${volume(l)} kg</strong></div><div><small>KCAL</small><strong>${l.kcal||'—'}</strong></div></div><div class="detail-list">${l.ex.map(e=>`<article><div><i>${muscleIcon(e.group)}</i><span><h2>${esc(e.name)}</h2><small>${e.group}</small></span></div>${e.sets.filter(s=>s.done!==false).map((s,i)=>`<p><b>${i+1}</b><span>${s.kg} kg</span><span>${s.reps} powt.</span><span>RPE ${s.rpe||'—'}</span></p>`).join('')}</article>`).join('')}</div></section>`;document.querySelector('#back-history').onclick=()=>{view=null;render()}}
function statsPage(){const weeks=Array.from({length:8},(_,i)=>{const end=new Date();end.setDate(end.getDate()-(7-i)*7);const start=new Date(end);start.setDate(start.getDate()-6);return logs.filter(l=>{const d=new Date(l.date);return d>=start&&d<=end})}),max=Math.max(...weeks.map(w=>w.length),1),records={};logs.forEach(l=>l.ex.forEach(e=>e.sets.forEach(s=>records[e.name]=Math.max(records[e.name]||0,Number(s.kg)||0))));page('Postępy','TWOJE LICZBY',`<div class="stats-top"><article><small>WSZYSTKIE TRENINGI</small><strong>${logs.length}</strong><span>od początku</span></article><article><small>ŁĄCZNY CZAS</small><strong>${logs.reduce((a,l)=>a+(l.minutes||0),0)}</strong><span>minut</span></article><article><small>ŁĄCZNA OBJĘTOŚĆ</small><strong>${Math.round(logs.reduce((a,l)=>a+volume(l),0))}</strong><span>kg</span></article></div><div class="stats-grid"><article class="chart"><small>REGULARNOŚĆ · 8 TYGODNI</small><h2>Liczba treningów</h2><div class="bars">${weeks.map((w,i)=>`<div><i><span style="height:${Math.max(4,w.length/max*100)}%"></span></i><b>${w.length}</b><small>${i===7?'teraz':7-i+' t.'}</small></div>`).join('')}</div></article><article class="chart records"><small>REKORDY</small><h2>Największy ciężar</h2>${Object.entries(records).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([n,v],i)=>`<div><span>${i+1}</span><b>${esc(n)}</b><strong>${v} kg</strong></div>`).join('')||'<p>Rekordy pojawią się po treningu.</p>'}</article></div><div class="chart weight-chart"><div><small>MASA CIAŁA</small><h2>Ostatnie pomiary</h2></div>${weights.length?`<div class="weight-line">${weights.slice(0,8).reverse().map((w,i)=>`<span style="height:${40+(w.value-Math.min(...weights.map(x=>x.value)))*7}px"><b>${w.value}</b><small>${new Date(w.date).toLocaleDateString('pl',{day:'numeric',month:'short'})}</small></span>`).join('')}</div>`:'<p>Dodaj pomiar na dashboardzie, aby zobaczyć trend.</p>'}</div>`)}
function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;view=null;render()});document.querySelectorAll('.begin').forEach(b=>b.onclick=()=>startWorkout(plans.find(p=>p.id===b.dataset.id)));document.querySelector('#quick')?.addEventListener('click',()=>startWorkout({id:uid(),name:'Mój trening',focus:'Trening własny',minutes:0,ex:[]}));document.querySelector('#add-weight')?.addEventListener('click',()=>{const v=prompt('Podaj aktualną masę ciała w kg:');if(v&&Number(v)>0){weights.unshift({date:new Date().toISOString(),value:Number(v)});save();render()}});document.querySelector('#new-plan')?.addEventListener('click',()=>{editing={id:uid(),name:'Nowy plan',focus:'Własny zestaw',minutes:35,ex:[]};render()});document.querySelectorAll('.edit-plan').forEach(b=>b.onclick=()=>{editing=structuredClone(plans.find(p=>p.id===b.dataset.id));render()});document.querySelectorAll('.close').forEach(b=>b.onclick=()=>{editing=null;render()});document.querySelector('#pick-ex')?.addEventListener('click',()=>{syncEditor();pickerFor='plan';render()});document.querySelector('#save-plan')?.addEventListener('click',()=>{syncEditor();const i=plans.findIndex(p=>p.id===editing.id);i<0?plans.push(editing):plans[i]=editing;editing=null;save();render()});document.querySelectorAll('.drop-ex').forEach(b=>b.onclick=()=>{syncEditor();editing.ex.splice(+b.dataset.i,1);render()});bindPicker();document.querySelectorAll('.log').forEach(b=>b.onclick=()=>{view='log:'+b.dataset.id;render()});if(view==='workout')workout()}
function bindPicker(){document.querySelector('#close-picker')?.addEventListener('click',()=>{pickerFor=null;render()});document.querySelector('#search-ex')?.addEventListener('input',e=>{const q=e.target.value;clearTimeout(window.exerciseSearchTimer);window.exerciseSearchTimer=setTimeout(()=>{filters.q=q;render();document.querySelector('#search-ex')?.focus()},250)});document.querySelectorAll('.group-chip').forEach(b=>b.onclick=()=>{filters.group=b.dataset.v;render()});document.querySelector('#gear-filter')?.addEventListener('change',e=>{filters.gear=e.target.value;render()});document.querySelectorAll('.choose-ex').forEach(b=>b.onclick=()=>addPicked(LIB.find(e=>e.id===b.dataset.id)));document.querySelector('#custom-ex')?.addEventListener('click',()=>{const n=prompt('Nazwa własnego ćwiczenia:');if(n)addPicked({name:n,group:'Własne',gear:'Inne'})})}
function addPicked(e){const target=makeEx(e.name,e.group,e.gear,3,10,0);if(pickerFor==='plan')editing.ex.push(target);else active.ex.push(target);pickerFor=null;render()}
function syncEditor(){if(!editing)return;editing.name=document.querySelector('#pn')?.value||editing.name;editing.focus=document.querySelector('#pf')?.value||editing.focus;document.querySelectorAll('.plan-sets').forEach(el=>{const e=editing.ex[+el.dataset.i],n=Math.max(1,+el.value||1);while(e.sets.length<n)e.sets.push({reps:10,kg:0,done:false});e.sets=e.sets.slice(0,n)})}
function bindWorkout(){document.querySelector('#quit').onclick=()=>{if(confirm('Zakończyć bez zapisywania?')){clearInterval(timerId);active=null;view=null;render()}};document.querySelector('#finish-workout').onclick=()=>{view='finish';clearInterval(timerId);finishPage()};document.querySelectorAll('.set-row input').forEach(el=>el.onchange=()=>{const s=active.ex[+el.dataset.e].sets[+el.dataset.s];s[el.dataset.f]=el.dataset.f==='rpe'?(el.value?+el.value:''):+el.value});document.querySelectorAll('.toggle-set').forEach(b=>b.onclick=()=>{active.ex[+b.dataset.e].sets[+b.dataset.s].done=!active.ex[+b.dataset.e].sets[+b.dataset.s].done;workout()});document.querySelectorAll('.add-set').forEach(b=>b.onclick=()=>{const e=active.ex[+b.dataset.e],last=e.sets.at(-1)||{reps:10,kg:0};e.sets.push({...last,done:false});workout()});document.querySelectorAll('.remove-active').forEach(b=>b.onclick=()=>{if(confirm('Usunąć ćwiczenie z treningu?')){active.ex.splice(+b.dataset.e,1);workout()}});document.querySelector('#add-active-ex').onclick=()=>{pickerFor='active';workout()};bindPicker()}
function bindFinish(){document.querySelector('#back-workout').onclick=()=>{view='workout';workout()};document.querySelector('#save-workout').onclick=()=>{const elapsed=Math.max(1,Math.round((Date.now()-started)/60000));logs.unshift({id:uid(),date:new Date().toISOString(),name:active.name,focus:active.focus,minutes:elapsed,kcal:+document.querySelector('#fkcal').value||0,bpm:+document.querySelector('#fbpm').value||0,feel:document.querySelector('#ffeel').value,ex:active.ex});save();active=null;view=null;tab='history';render()}}
function recent(n){const d=new Date();d.setDate(d.getDate()-n);return logs.filter(l=>new Date(l.date)>=d)}function volume(l){return Math.round((l.ex||[]).reduce((a,e)=>a+(e.sets||[]).filter(s=>s.done!==false).reduce((b,s)=>b+(Number(s.kg)||0)*(Number(s.reps)||0),0),0))}function previous(name){for(const l of logs){const e=l.ex.find(x=>x.name===name);if(e){const best=Math.max(...e.sets.map(s=>Number(s.kg)||0));return `${best} kg · ${e.sets.length} serie`}}return ''}function getStreak(){let n=0,d=new Date(),days=new Set(logs.map(l=>new Date(l.date).toISOString().slice(0,10)));while(days.has(d.toISOString().slice(0,10))){n++;d.setDate(d.getDate()-1)}return n}function time(ms){const s=Math.floor(ms/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}function delta(v){return(v>0?'+':'')+v.toFixed(1)}function muscleIcon(g){return({Nogi:'◒',Pośladki:'◉',Plecy:'↟',Klatka:'◇',Barki:'△',Ramiona:'⌁',Core:'◎',Kondycja:'ϟ',Mobilność:'∞',Własne:'✦'}[g]||'◆')}
// --- v3: bezpieczeństwo danych, elastyczne ćwiczenia i zaawansowany dziennik ---
let favorites=JSON.parse(localStorage.getItem('hwt-favorites')||'[]'),recentExercises=JSON.parse(localStorage.getItem('hwt-recent-exercises')||'[]'),ownedGear=JSON.parse(localStorage.getItem('hwt-owned-gear')||'["Hantle","Taśma","Mata","Masa ciała"]'),exerciseProfiles=JSON.parse(localStorage.getItem('hwt-exercise-profiles')||'{}'),draft=JSON.parse(localStorage.getItem('hwt-active-draft')||'null'),restEnd=0,restTimer=null,editLogId=null,pickerMode='all';
function inferType(name,group){name=name.toLowerCase();if(/marsz|shadow|step touch|mobilizacja|rozciąganie|pozycja|pies z głową|skłon boczny|plank|wall sit/.test(name)||group==='Mobilność'||group==='Rozciąganie')return'time';if(/monster|bear crawl/.test(name))return'steps';return'reps'}
LIB.forEach(e=>{e.type=inferType(e.name,e.group);Object.assign(e,inferExerciseConfig(e))});[...plans,...logs].forEach(p=>(p.ex||[]).forEach(normalizeExercise));
const originalSave=save;save=function(){originalSave();localStorage.setItem('hwt-favorites',JSON.stringify(favorites));localStorage.setItem('hwt-recent-exercises',JSON.stringify(recentExercises));localStorage.setItem('hwt-owned-gear',JSON.stringify(ownedGear));localStorage.setItem('hwt-exercise-profiles',JSON.stringify(exerciseProfiles))};
function persistDraft(){if(!active)return;localStorage.setItem('hwt-active-draft',JSON.stringify({active,started,view:'workout',savedAt:Date.now()}))}function clearDraft(){localStorage.removeItem('hwt-active-draft');draft=null}
function localDay(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return`${y}-${m}-${day}`}function monday(d=new Date()){const x=new Date(d);x.setHours(0,0,0,0);x.setDate(x.getDate()-((x.getDay()+6)%7));return x}
function startWorkout(p){active=structuredClone(p);active.ex.forEach(e=>{e.type=e.type||inferType(e.name,e.group);e.rest=e.rest||60;e.note=e.note||'';e.sets.forEach(s=>s.done=false)});started=Date.now();view='workout';tab='home';persistDraft();timerId&&clearInterval(timerId);timerId=setInterval(()=>{const el=document.querySelector('#timer');if(el)el.textContent=time(Date.now()-started);if(active)persistDraft()},5000);render()}
function recoveryBanner(){return draft?`<div class="recovery"><div><b>Niedokończony trening</b><small>Zapisano ${new Date(draft.savedAt).toLocaleString('pl')}</small></div><button id="recover">Kontynuuj</button><button id="discard-draft">Odrzuć</button></div>`:''}
function home(){const start=monday(),week=logs.filter(l=>new Date(l.date)>=start).length,vol=logs.filter(l=>new Date(l.date)>=start).reduce((a,l)=>a+volume(l),0),last=logs[0],streak=getStreak();page('Cześć!','TWÓJ DASHBOARD',`${recoveryBanner()}<div class="home-primary"><button id="quick">＋ Rozpocznij pusty trening</button><span>albo wybierz zapisany plan poniżej</span></div><div class="hero-card"><div><small>AKTYWNOŚĆ · 12 TYGODNI</small><h2>${logs.length?`${logs.length} wykonanych treningów`:'Zacznij budować regularność'}</h2></div><span class="streak">${streak} <small>dni serii</small></span>${heatmap()}</div><div class="kpis"><article><small>TEN TYDZIEŃ</small><strong>${week}<em>/ 3</em></strong><span>treningi od poniedziałku</span></article><article><small>OBJĘTOŚĆ</small><strong>${Math.round(vol)}<em> kg</em></strong><span>w tym tygodniu</span></article><article><small>OSTATNI TRENING</small><strong class="text">${last?esc(last.name):'—'}</strong><span>${last?new Date(last.date).toLocaleDateString('pl'):'brak danych'}</span></article></div><div class="section-title"><div><small>NA DZIŚ</small><h2>Wybierz trening</h2></div></div><div class="programs">${plans.slice(0,3).map((p,i)=>`<article class="program c${i}"><span>0${i+1}</span><div><h3>${esc(p.name)}</h3><p>${esc(p.focus)} · ${p.ex.length} ćwiczeń</p></div><button class="begin" data-id="${p.id}">Start</button></article>`).join('')}</div><div class="weight-card"><div><small>MASA CIAŁA</small><h2>${weights[0]?weights[0].value+' kg':'Dodaj pierwszy pomiar'}</h2><p>${weights.length>1?delta(weights[0].value-weights[1].value)+' kg od poprzedniego pomiaru':'Śledź zmianę w czasie'}</p></div><button id="add-weight">＋ Pomiar</button></div><section class="settings-card"><div><small>DANE I USTAWIENIA</small><h2>Kopia zapasowa</h2><p>Eksportuj dane przed zmianą telefonu lub adresu strony.</p></div><div><button id="export-json">Eksport JSON</button><button id="export-csv">Eksport CSV</button><label class="import-label">Import JSON<input id="import-json" type="file" accept="application/json"></label><button id="gear-settings">Mój sprzęt</button></div></section>`)}
const oldBind=bind;bind=function(){oldBind();document.querySelector('#recover')?.addEventListener('click',()=>{active=draft.active;started=draft.started||Date.now();view='workout';timerId=setInterval(()=>{const el=document.querySelector('#timer');if(el)el.textContent=time(Date.now()-started)},1000);render()});document.querySelector('#discard-draft')?.addEventListener('click',()=>{clearDraft();render()});document.querySelector('#export-json')?.addEventListener('click',exportJSON);document.querySelector('#export-csv')?.addEventListener('click',exportCSV);document.querySelector('#import-json')?.addEventListener('change',importJSON);document.querySelector('#gear-settings')?.addEventListener('click',gearSettings)};
function picker(){const groups=['Wszystkie',...new Set(LIB.map(e=>e.group))],gears=['Wszystkie',...new Set(LIB.map(e=>e.gear))];let list=LIB.filter(e=>(filters.group==='Wszystkie'||e.group===filters.group)&&(filters.gear==='Wszystkie'||e.gear===filters.gear)&&e.name.toLowerCase().includes(filters.q.toLowerCase()));if(pickerMode==='favorites')list=list.filter(e=>favorites.includes(e.name));if(pickerMode==='recent')list=list.sort((a,b)=>recentExercises.indexOf(a.name)-recentExercises.indexOf(b.name)).filter(e=>recentExercises.includes(e.name));if(pickerMode==='owned')list=list.filter(e=>ownedGear.includes(e.gear));return `<div class="overlay picker-layer"><div class="modal picker"><div class="modal-head"><div><small>BIBLIOTEKA</small><h2>Wybierz ćwiczenie</h2></div><button id="close-picker">×</button></div><div class="picker-tabs"><button data-mode="all" class="${pickerMode==='all'?'on':''}">Wszystkie</button><button data-mode="owned" class="${pickerMode==='owned'?'on':''}">Mój sprzęt</button><button data-mode="favorites" class="${pickerMode==='favorites'?'on':''}">★ Ulubione</button><button data-mode="recent" class="${pickerMode==='recent'?'on':''}">Ostatnie</button></div><div class="search"><input id="search-ex" placeholder="Szukaj ćwiczenia…" value="${esc(filters.q)}"><button id="custom-ex">＋ Własne</button></div><div class="chips">${groups.map(g=>`<button class="group-chip ${filters.group===g?'on':''}" data-v="${g}">${g}</button>`).join('')}</div><select id="gear-filter">${gears.map(g=>`<option ${filters.gear===g?'selected':''}>${g}</option>`).join('')}</select><div class="library-list">${list.map(e=>`<div class="library-item"><button class="favorite-ex ${favorites.includes(e.name)?'on':''}" data-name="${esc(e.name)}" aria-label="Dodaj do ulubionych">★</button><button class="choose-ex" data-id="${e.id}"><i>${muscleIcon(e.group)}</i><span><b>${esc(e.name)}</b><small>${e.group} · ${e.gear} · ${typeLabel(e.type)}</small></span><em>＋</em></button></div>`).join('')||'<p class="empty-line">Brak wyników. Dodaj własne ćwiczenie.</p>'}</div></div></div>`}
function bindPicker(){document.querySelector('#close-picker')?.addEventListener('click',()=>{pickerFor=null;render()});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{pickerMode=b.dataset.mode;render()});document.querySelector('#search-ex')?.addEventListener('input',e=>{const q=e.target.value;clearTimeout(window.exerciseSearchTimer);window.exerciseSearchTimer=setTimeout(()=>{filters.q=q;render();document.querySelector('#search-ex')?.focus()},250)});document.querySelectorAll('.group-chip').forEach(b=>b.onclick=()=>{filters.group=b.dataset.v;render()});document.querySelector('#gear-filter')?.addEventListener('change',e=>{filters.gear=e.target.value;render()});document.querySelectorAll('.favorite-ex').forEach(b=>b.onclick=()=>{favorites=favorites.includes(b.dataset.name)?favorites.filter(x=>x!==b.dataset.name):[...favorites,b.dataset.name];save();render()});document.querySelectorAll('.choose-ex').forEach(b=>b.onclick=()=>addPicked(LIB.find(e=>e.id===b.dataset.id)));document.querySelector('#custom-ex')?.addEventListener('click',()=>customExercise())}
function customExercise(){const name=prompt('Nazwa własnego ćwiczenia:');if(!name)return;const type=prompt('Typ pomiaru: powtórzenia, czas lub kroki','powtórzenia');addPicked({name,group:'Własne',gear:'Inne',type:type?.toLowerCase().startsWith('czas')?'time':type?.toLowerCase().startsWith('krok')?'steps':'reps'})}
function addPicked(e){const target=makeEx(e.name,e.group,e.gear,3,10,0);target.type=e.type||inferType(e.name,e.group);target.rest=60;target.note='';target.unilateral=false;recentExercises=[e.name,...recentExercises.filter(x=>x!==e.name)].slice(0,15);save();if(pickerFor==='plan')editing.ex.push(target);else active.ex.push(target);pickerFor=null;persistDraft();render()}
function exerciseCard(e,ei){const prev=previous(e.name),best=previousBest(e.name),cols=e.type==='reps'?['KG','POWT.']:e.type==='time'?['SEK.','–']:['KROKI','–'];return `<article class="active-card"><div class="active-title"><i>${muscleIcon(e.group)}</i><div><button class="exercise-history" data-name="${esc(e.name)}"><h2>${esc(e.name)} ›</h2></button><small>${prev?`Poprzednio: ${prev}`:`${e.group} · ${e.gear}`}</small></div><button class="remove-active" data-e="${ei}">•••</button></div>${e.note?`<p class="exercise-note">${esc(e.note)}</p>`:''}<div class="set-head"><span>SERIA</span><span>${cols[0]}</span><span>${cols[1]}</span><span>RPE <button class="rpe-help">?</button></span><span>✓</span></div>${e.sets.map((s,si)=>setRow(e,s,ei,si)).join('')}<div class="exercise-tools"><button class="add-set" data-e="${ei}">＋ Seria</button><button class="copy-set" data-e="${ei}">⧉ Kopiuj</button><button class="toggle-warmup" data-e="${ei}">W Rozgrz.</button><button class="edit-exercise" data-e="${ei}">⚙</button></div></article>`}
function setRow(e,s,ei,si){let fields=e.type==='reps'?`<input data-e="${ei}" data-s="${si}" data-f="kg" type="number" inputmode="decimal" value="${s.kg||0}"><input data-e="${ei}" data-s="${si}" data-f="reps" type="number" inputmode="numeric" value="${s.reps||0}">`:e.type==='time'?`<input data-e="${ei}" data-s="${si}" data-f="seconds" type="number" inputmode="numeric" value="${s.seconds||30}"><span class="na">—</span>`:`<input data-e="${ei}" data-s="${si}" data-f="steps" type="number" inputmode="numeric" value="${s.steps||20}"><span class="na">—</span>`;return `<div class="set-row ${s.done?'done':''} ${s.warmup?'warmup':''}"><b>${s.warmup?'W':si+1}</b>${fields}<input data-e="${ei}" data-s="${si}" data-f="rpe" type="number" inputmode="decimal" placeholder="–" value="${s.rpe||''}"><button class="toggle-set" data-e="${ei}" data-s="${si}">${s.done?'✓':'○'}</button></div>`}
function bindWorkout(){document.querySelector('#quit').onclick=()=>{if(confirm('Zakończyć bez zapisywania?')){clearInterval(timerId);clearDraft();active=null;view=null;render()}};document.querySelector('#finish-workout').onclick=()=>{syncActiveInputs();view='finish';clearInterval(timerId);persistDraft();finishPage()};document.querySelectorAll('.set-row input').forEach(el=>el.onchange=()=>{const s=active.ex[+el.dataset.e].sets[+el.dataset.s];s[el.dataset.f]=el.dataset.f==='rpe'?(el.value?+el.value:''):+el.value;persistDraft()});document.querySelectorAll('.toggle-set').forEach(b=>b.onclick=()=>{syncActiveInputs();const e=active.ex[+b.dataset.e],s=e.sets[+b.dataset.s];s.done=!s.done;if(s.done){checkRecord(e,s);startRest(e.rest||60)}persistDraft();workout()});document.querySelectorAll('.add-set').forEach(b=>b.onclick=()=>{syncActiveInputs();const e=active.ex[+b.dataset.e],last=e.sets.at(-1)||{reps:10,kg:0};e.sets.push({...last,done:false,warmup:false});persistDraft();workout()});document.querySelectorAll('.copy-set').forEach(b=>b.onclick=()=>{syncActiveInputs();const e=active.ex[+b.dataset.e],last=e.sets.at(-1)||{reps:10,kg:0};e.sets.push({...last,done:false,warmup:false});persistDraft();workout()});document.querySelectorAll('.toggle-warmup').forEach(b=>b.onclick=()=>{const e=active.ex[+b.dataset.e];e.sets.push({reps:10,kg:0,rpe:'',done:false,warmup:true,seconds:30,steps:20});persistDraft();workout()});document.querySelectorAll('.edit-exercise').forEach(b=>b.onclick=()=>editExerciseSettings(+b.dataset.e));document.querySelectorAll('.remove-active').forEach(b=>b.onclick=()=>{if(confirm('Usunąć ćwiczenie z treningu?')){active.ex.splice(+b.dataset.e,1);persistDraft();workout()}});document.querySelectorAll('.rpe-help').forEach(b=>b.onclick=()=>alert('RPE 6: ok. 4 powtórzenia w zapasie\nRPE 7: 3 w zapasie\nRPE 8: 2 w zapasie\nRPE 9: 1 w zapasie\nRPE 10: brak zapasu'));document.querySelectorAll('.exercise-history').forEach(b=>b.onclick=()=>{syncActiveInputs();view='exercise:'+encodeURIComponent(b.dataset.name);tab='history';render()});document.querySelector('#add-active-ex').onclick=()=>{syncActiveInputs();pickerFor='active';workout()};bindPicker();renderRest()}
function syncActiveInputs(){document.querySelectorAll('.set-row input').forEach(el=>{const s=active?.ex[+el.dataset.e]?.sets[+el.dataset.s];if(s)s[el.dataset.f]=el.dataset.f==='rpe'?(el.value?+el.value:''):+el.value})}
function editExerciseSettings(i){const e=active.ex[i],rest=prompt('Czas przerwy po serii (sekundy):',e.rest||60),note=prompt('Notatka do ćwiczenia:',e.note||'');e.rest=Math.max(0,+rest||0);e.note=note||'';e.unilateral=confirm('Czy ćwiczenie wykonujesz osobno na lewą i prawą stronę?');persistDraft();workout()}
function startRest(seconds){if(!seconds)return;restEnd=Date.now()+seconds*1000;clearInterval(restTimer);restTimer=setInterval(renderRest,1000)}function renderRest(){let el=document.querySelector('#rest-float'),left=Math.ceil((restEnd-Date.now())/1000);if(left<=0){clearInterval(restTimer);el?.remove();return}if(!el){el=document.createElement('div');el.id='rest-float';el.innerHTML='<span>PRZERWA</span><b></b><button>Pomijam</button>';document.body.appendChild(el);el.querySelector('button').onclick=()=>{restEnd=0;renderRest()}}el.querySelector('b').textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`}
function finishPage(){syncActiveInputs();const ms=Date.now()-started;app.innerHTML=`<section class="finish-page"><div class="success">✓</div><label>TRENING ZAKOŃCZONY</label><h1>Dobra robota!</h1><div class="summary-kpis"><div><small>CZAS</small><strong>${time(ms)}</strong></div><div><small>SERIE</small><strong>${active.ex.reduce((a,e)=>a+e.sets.filter(s=>s.done&&!s.warmup).length,0)}</strong></div><div><small>OBJĘTOŚĆ</small><strong>${volume({ex:active.ex})} kg</strong></div></div><div class="finish-form"><label>Data treningu<input id="fdate" type="date" value="${localDay()}"></label><label>Spalone kalorie<input id="fkcal" type="number" placeholder="0"><span>kcal</span></label><label>Średnie tętno<input id="fbpm" type="number" placeholder="0"><span>bpm</span></label><label>Jak było?<select id="ffeel"><option>Świetnie</option><option selected>W porządku</option><option>Ciężko</option><option>Bardzo ciężko</option></select></label><label>Ból / dyskomfort 0–10<input id="fpain" type="number" min="0" max="10" value="0"></label><label>Notatka<textarea id="fnotes" placeholder="Co zapamiętać na następny trening?"></textarea></label></div><button id="save-workout" class="primary wide">Zapisz trening</button><button id="back-workout" class="ghost">Wróć do treningu</button></section>`;bindFinish()}
function bindFinish(){document.querySelector('#back-workout').onclick=()=>{view='workout';workout()};document.querySelector('#save-workout').onclick=()=>{const elapsed=Math.max(1,Math.round((Date.now()-started)/60000)),date=document.querySelector('#fdate').value+'T12:00:00';logs.unshift({id:uid(),date:new Date(date).toISOString(),name:active.name,focus:active.focus,minutes:elapsed,kcal:+document.querySelector('#fkcal').value||0,bpm:+document.querySelector('#fbpm').value||0,feel:document.querySelector('#ffeel').value,pain:+document.querySelector('#fpain').value||0,notes:document.querySelector('#fnotes').value,ex:active.ex});clearDraft();save();active=null;view=null;tab='history';render()}}
function historyPage(){if(view?.startsWith('log:'))return logDetail(view.split(':')[1]);if(view?.startsWith('exercise:'))return exerciseDetail(decodeURIComponent(view.slice(9)));page('Historia','TWOJE SESJE',logs.length?`<div class="log-list">${logs.map(l=>`<button class="log" data-id="${l.id}"><div class="date"><strong>${new Date(l.date).getDate()}</strong><span>${new Date(l.date).toLocaleDateString('pl',{month:'short'})}</span></div><div><h2>${esc(l.name)}</h2><p>${l.ex.length} ćwiczeń · ${l.minutes||0} min</p><small>${volume(l)} kg objętości　${l.kcal||'—'} kcal　${l.bpm||'—'} bpm</small></div><em>›</em></button>`).join('')}</div>`:`<div class="empty"><i>◷</i><h2>Brak zapisanych sesji</h2><p>Wykonany trening pojawi się tutaj.</p><button data-tab="home" class="primary">Wybierz trening</button></div>`)}
function logDetail(id){const l=logs.find(x=>x.id===id);if(!l){view=null;return historyPage()}if(editLogId===id)return editLog(l);app.innerHTML=`<section><div class="detail-actions"><button id="back-history" class="back">← Historia</button><span><button id="edit-log">Edytuj</button><button id="delete-log">Usuń</button></span></div><label>${new Date(l.date).toLocaleDateString('pl',{weekday:'long',day:'numeric',month:'long'})}</label><h1>${esc(l.name)}</h1><div class="summary-kpis"><div><small>CZAS</small><strong>${l.minutes||0} min</strong></div><div><small>OBJĘTOŚĆ</small><strong>${volume(l)} kg</strong></div><div><small>KCAL</small><strong>${l.kcal||'—'}</strong></div></div>${l.notes?`<div class="session-note">${esc(l.notes)}</div>`:''}<div class="detail-list">${l.ex.map(e=>`<article><button class="open-exercise" data-name="${esc(e.name)}"><div><i>${muscleIcon(e.group)}</i><span><h2>${esc(e.name)} ›</h2><small>${e.group}</small></span></div></button>${e.sets.filter(s=>s.done!==false).map((s,i)=>`<p><b>${s.warmup?'W':i+1}</b>${metricCells(e,s)}<span>RPE ${s.rpe||'—'}</span></p>`).join('')}</article>`).join('')}</div></section>`;document.querySelector('#back-history').onclick=()=>{view=null;render()};document.querySelector('#edit-log').onclick=()=>{editLogId=id;render()};document.querySelector('#delete-log').onclick=()=>{if(confirm('Trwale usunąć ten trening?')){logs=logs.filter(x=>x.id!==id);save();view=null;render()}};document.querySelectorAll('.open-exercise').forEach(b=>b.onclick=()=>{view='exercise:'+encodeURIComponent(b.dataset.name);render()})}
function editLog(l){app.innerHTML=`<section class="edit-log"><button id="cancel-edit-log" class="back">← Anuluj</button><label>EDYCJA SESJI</label><h1>${esc(l.name)}</h1><div class="finish-form"><label>Nazwa<input id="elname" value="${esc(l.name)}"></label><label>Data<input id="eldate" type="date" value="${localDay(new Date(l.date))}"></label><label>Czas<input id="elminutes" type="number" value="${l.minutes||0}"><span>min</span></label><label>Kalorie<input id="elkcal" type="number" value="${l.kcal||0}"><span>kcal</span></label><label>Tętno<input id="elbpm" type="number" value="${l.bpm||0}"><span>bpm</span></label><label>Notatka<textarea id="elnotes">${esc(l.notes||'')}</textarea></label></div><div class="edit-log-ex">${l.ex.map((e,ei)=>`<article><h2>${esc(e.name)}</h2>${e.sets.map((s,si)=>`<div><b>${si+1}</b><input data-e="${ei}" data-s="${si}" data-f="kg" type="number" value="${s.kg||0}"><input data-e="${ei}" data-s="${si}" data-f="reps" type="number" value="${s.reps||0}"><button class="delete-log-set" data-e="${ei}" data-s="${si}">×</button></div>`).join('')}</article>`).join('')}</div><button id="save-log-edit" class="primary wide">Zapisz zmiany</button></section>`;document.querySelector('#cancel-edit-log').onclick=()=>{editLogId=null;render()};document.querySelectorAll('.delete-log-set').forEach(b=>b.onclick=()=>{l.ex[+b.dataset.e].sets.splice(+b.dataset.s,1);editLog(l)});document.querySelector('#save-log-edit').onclick=()=>{l.name=document.querySelector('#elname').value;l.date=new Date(document.querySelector('#eldate').value+'T12:00:00').toISOString();l.minutes=+document.querySelector('#elminutes').value;l.kcal=+document.querySelector('#elkcal').value;l.bpm=+document.querySelector('#elbpm').value;l.notes=document.querySelector('#elnotes').value;document.querySelectorAll('.edit-log-ex input').forEach(el=>l.ex[+el.dataset.e].sets[+el.dataset.s][el.dataset.f]=+el.value);save();editLogId=null;render()}}
function exerciseDetail(name){const entries=logs.flatMap(l=>{const e=l.ex.find(x=>x.name===name);return e?[{date:l.date,e}]:[]}),best=Math.max(0,...entries.flatMap(x=>x.e.sets.map(s=>Number(s.kg)||0))),maxVol=Math.max(0,...entries.map(x=>volume({ex:[x.e]})));app.innerHTML=`<section><button id="back-exercise" class="back">← Historia</button><label>HISTORIA ĆWICZENIA</label><h1>${esc(name)}</h1><div class="summary-kpis"><div><small>WYKONANIA</small><strong>${entries.length}</strong></div><div><small>NAJWIĘKSZY CIĘŻAR</small><strong>${best} kg</strong></div><div><small>MAX OBJĘTOŚĆ</small><strong>${maxVol} kg</strong></div></div><div class="exercise-trend">${entries.slice(0,10).reverse().map(x=>`<i style="height:${20+(volume({ex:[x.e]})/Math.max(maxVol,1))*100}px"><b>${volume({ex:[x.e]})}</b><small>${new Date(x.date).toLocaleDateString('pl',{day:'numeric',month:'short'})}</small></i>`).join('')}</div><div class="exercise-entries">${entries.map(x=>`<article><small>${new Date(x.date).toLocaleDateString('pl',{weekday:'short',day:'numeric',month:'long'})}</small>${x.e.sets.filter(s=>s.done!==false).map((s,i)=>`<p><b>${i+1}</b>${metricCells(x.e,s)}<span>RPE ${s.rpe||'—'}</span></p>`).join('')}</article>`).join('')||'<p>Brak zapisów.</p>'}</div></section>`;document.querySelector('#back-exercise').onclick=()=>{view=null;render()}}
function statsPage(){const weeks=Array.from({length:8},(_,i)=>{const start=monday();start.setDate(start.getDate()-(7-i)*7);const end=new Date(start);end.setDate(end.getDate()+7);return logs.filter(l=>new Date(l.date)>=start&&new Date(l.date)<end)}),max=Math.max(...weeks.map(w=>w.length),1),records={};logs.forEach(l=>l.ex.forEach(e=>e.sets.forEach(s=>records[e.name]=Math.max(records[e.name]||0,Number(s.kg)||0))));page('Postępy','TWOJE LICZBY',`<div class="stats-top"><article><small>WSZYSTKIE TRENINGI</small><strong>${logs.length}</strong><span>od początku</span></article><article><small>ŁĄCZNY CZAS</small><strong>${logs.reduce((a,l)=>a+(l.minutes||0),0)}</strong><span>minut</span></article><article><small>ŁĄCZNA OBJĘTOŚĆ</small><strong>${Math.round(logs.reduce((a,l)=>a+volume(l),0))}</strong><span>kg</span></article></div><div class="stats-grid"><article class="chart"><small>REGULARNOŚĆ · 8 TYGODNI</small><h2>Liczba treningów</h2><div class="bars">${weeks.map((w,i)=>`<div><i><span style="height:${Math.max(4,w.length/max*100)}%"></span></i><b>${w.length}</b><small>${i===7?'teraz':7-i+' t.'}</small></div>`).join('')}</div></article><article class="chart records"><small>REKORDY</small><h2>Największy ciężar</h2>${Object.entries(records).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([n,v],i)=>`<button class="stat-exercise" data-name="${esc(n)}"><span>${i+1}</span><b>${esc(n)}</b><strong>${v} kg</strong></button>`).join('')||'<p>Rekordy pojawią się po treningu.</p>'}</article></div><div class="chart weight-chart"><div><small>MASA CIAŁA</small><h2>Ostatnie pomiary</h2></div>${weights.length?`<div class="weight-line">${weights.slice(0,8).reverse().map(w=>`<span style="height:${40+(w.value-Math.min(...weights.map(x=>x.value)))*7}px"><b>${w.value}</b><small>${new Date(w.date).toLocaleDateString('pl',{day:'numeric',month:'short'})}</small></span>`).join('')}</div>`:'<p>Dodaj pomiar na dashboardzie, aby zobaczyć trend.</p>'}</div>`);document.querySelectorAll('.stat-exercise').forEach(b=>b.onclick=()=>{view='exercise:'+encodeURIComponent(b.dataset.name);tab='history';render()})}
function previousBest(name){let kg=0,reps=0;logs.forEach(l=>{const e=l.ex.find(x=>x.name===name);e?.sets.forEach(s=>{if(+s.kg>kg||(+s.kg===kg&&+s.reps>reps)){kg=+s.kg;reps=+s.reps}})});return{kg,reps}}function checkRecord(e,s){if(e.type!=='reps')return;const b=previousBest(e.name);if(+s.kg>b.kg||(+s.kg===b.kg&&+s.reps>b.reps))toast(`Nowy rekord: ${e.name} — ${s.kg} kg × ${s.reps}`)}function toast(msg){const t=document.createElement('div');t.className='toast';t.textContent='★ '+msg;document.body.appendChild(t);setTimeout(()=>t.remove(),3500)}function metricCells(e,s){if(e.type==='time')return`<span>${s.seconds||0} sek.</span><span>czas</span>`;if(e.type==='steps')return`<span>${s.steps||0}</span><span>kroków</span>`;return`<span>${s.kg||0} kg</span><span>${s.reps||0} powt.</span>`}function typeLabel(t){return t==='time'?'czas':t==='steps'?'kroki':'ciężar i powt.'}
function getStreak(){const days=new Set(logs.map(l=>localDay(new Date(l.date)))),d=new Date();if(!days.has(localDay(d)))d.setDate(d.getDate()-1);let n=0;while(days.has(localDay(d))){n++;d.setDate(d.getDate()-1)}return n}
function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}function exportJSON(){download(`treningi-backup-${localDay()}.json`,JSON.stringify({version:3,exportedAt:new Date().toISOString(),plans,logs,weights,favorites,recentExercises,ownedGear},null,2),'application/json')}function exportCSV(){const rows=[['data','trening','ćwiczenie','seria','rodzaj','kg','powtórzenia','sekundy','kroki','RPE','kcal','tętno']];logs.forEach(l=>l.ex.forEach(e=>e.sets.forEach((s,i)=>rows.push([localDay(new Date(l.date)),l.name,e.name,i+1,e.type||'reps',s.kg||'',s.reps||'',s.seconds||'',s.steps||'',s.rpe||'',l.kcal||'',l.bpm||'']))));download(`treningi-${localDay()}.csv`,rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(';')).join('\n'),'text/csv;charset=utf-8')}function importJSON(ev){const f=ev.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!d.logs||!d.plans)throw Error();if(confirm(`Import zastąpi obecne dane (${logs.length} treningów). Kontynuować?`)){plans=d.plans;logs=d.logs;weights=d.weights||[];favorites=d.favorites||[];recentExercises=d.recentExercises||[];ownedGear=d.ownedGear||ownedGear;save();render()}}catch{alert('Nie udało się odczytać kopii zapasowej.')}};r.readAsText(f)}function gearSettings(){const all=['Hantle','Taśma','Mata','Masa ciała','Ławka','Step','Inne'],answer=prompt('Wpisz posiadany sprzęt, oddzielając przecinkami:',ownedGear.join(', '));if(answer){ownedGear=answer.split(',').map(x=>x.trim()).filter(Boolean);save();alert('Zapisano: '+ownedGear.join(', '))}}

// --- v4: świadome liczenie obciążenia i stron, bez RPE ---
function inferExerciseConfig(e){const n=(e.name||'').toLowerCase(),gear=e.gear||'';let equipment=gear==='Hantle'?'dumbbells':gear==='Sztanga'?'barbell':gear==='Kettlebell'?'kettlebell':gear==='Taśma'?'band':/masa ciała|mata/i.test(gear)?'bodyweight':'other';let implementCount=equipment==='dumbbells'?2:1;if(/z hantlem|goblet|russian twist|hip thrust|przysiad sumo|prostowanie ramion nad głową/.test(n))implementCount=1;let sideMode=/bułgarski|jednorącz|wykrok w tył|wejście na podwyższenie|odwodzenie nogi|prostowanie nogi|przywodzenie nogi|clamshell|donkey kick|side plank|bird dog|pallof|łydki|tyłu uda|przodu uda|zginacza biodra|figura 4|gołębia|wykrok boczny|skręt kręgosłupa|barku w poprzek|tricepsa|szyi na bok/.test(n)?'per_side':'together';if(/wykroki chodzone|mountain climber|naprzemiennie/.test(n))sideMode='alternating_total';return{equipment,loadMode:equipment==='dumbbells'?'per_item':equipment==='barbell'||equipment==='kettlebell'?'total':'none',implementCount,sideMode}}
function normalizeExercise(e){const inferred=inferExerciseConfig(e),profile=exerciseProfiles[e.name]||{};e.type=e.type||inferType(e.name,e.group);e.rest=e.rest||60;e.note=e.note||'';for(const k of ['equipment','loadMode','implementCount','sideMode'])if(e[k]===undefined||e[k]===null)e[k]=profile[k]??inferred[k];delete e.unilateral;(e.sets||[]).forEach(s=>{s.seconds=s.seconds||0;s.steps=s.steps||0;s.warmup=!!s.warmup;delete s.rpe});return e}
function equipmentName(v){return({dumbbells:'hantle',barbell:'sztanga',kettlebell:'kettlebell',band:'taśma',bodyweight:'masa ciała',other:'inne'}[v]||'inne')}
function sideName(v,type='reps'){const measure=type==='time'?'czas':'powtórzenia';return v==='per_side'?`${measure} na stronę`:v==='alternating_total'?`${measure} łącznie`:'obie strony jednocześnie'}
function configSummary(e){normalizeExercise(e);const load=e.loadMode==='per_item'?(e.implementCount===2?'2 hantle · kg/hantel':'1 hantel · kg/hantel'):e.loadMode==='total'?`${equipmentName(e.equipment)} · ciężar łączny`:equipmentName(e.equipment);return`${load} · ${sideName(e.sideMode,e.type)}`}
function loadMultiplier(e){return e.loadMode==='per_item'?Math.max(1,Number(e.implementCount)||1):e.loadMode==='total'?1:0}
function sideMultiplier(e){return e.sideMode==='per_side'?2:1}
function setVolume(e,s){if(e.type!=='reps'||s.warmup||s.done===false)return 0;return(Number(s.kg)||0)*(Number(s.reps)||0)*loadMultiplier(e)*sideMultiplier(e)}
function volume(l){return Math.round((l.ex||[]).reduce((sum,e)=>{normalizeExercise(e);return sum+(e.sets||[]).reduce((v,s)=>v+setVolume(e,s),0)},0))}
function previous(name){for(const l of logs){const e=l.ex.find(x=>x.name===name);if(e){normalizeExercise(e);const best=Math.max(0,...e.sets.map(s=>Number(s.kg)||0));return`${best} ${loadUnit(e)} · ${e.sets.filter(s=>!s.warmup).length} serie`}}return''}
function loadUnit(e){if(e.equipment==='band')return'oporu';if(e.loadMode==='per_item')return'kg/hantel';if(e.loadMode==='total')return'kg łącznie';return''}
function startWorkout(p){active=structuredClone(p);active.ex.forEach(e=>{normalizeExercise(e);e.sets.forEach(s=>s.done=false)});started=Date.now();view='workout';tab='home';persistDraft();timerId&&clearInterval(timerId);timerId=setInterval(()=>{const el=document.querySelector('#timer');if(el)el.textContent=time(Date.now()-started);if(active)persistDraft()},5000);render()}
function addPicked(e){const target=normalizeExercise(makeEx(e.name,e.group,e.gear,e.group==='Rozciąganie'?1:3,10,0));target.type=e.type||inferType(e.name,e.group);if(e.group==='Rozciąganie')target.sets.forEach(s=>s.seconds=30);recentExercises=[e.name,...recentExercises.filter(x=>x!==e.name)].slice(0,15);save();if(pickerFor==='plan')editing.ex.push(target);else active.ex.push(target);pickerFor=null;persistDraft();render()}
function loadColumn(e){if(e.equipment==='band')return'OPÓR';if(e.loadMode==='per_item')return'KG/HANTEL';if(e.loadMode==='total')return'KG ŁĄCZNIE';return'–'}
function repsColumn(e){return e.sideMode==='per_side'?'POWT./STR.':e.sideMode==='alternating_total'?'POWT. ŁĄCZNIE':'POWT.'}
function exerciseCard(e,ei){normalizeExercise(e);const prev=previous(e.name),cols=e.type==='reps'?[loadColumn(e),repsColumn(e)]:e.type==='time'?['SEK.','–']:['KROKI','–'];return`<article class="active-card"><div class="active-title"><i>${muscleIcon(e.group)}</i><div><button class="exercise-history" data-name="${esc(e.name)}"><h2>${esc(e.name)} ›</h2></button><small>${prev?`Poprzednio: ${prev}`:`${e.group} · ${e.gear}`}</small><small class="exercise-config">${esc(configSummary(e))}</small></div><button class="remove-active" data-e="${ei}">•••</button></div>${e.note?`<p class="exercise-note">${esc(e.note)}</p>`:''}<div class="set-head compact"><span>SERIA</span><span>${cols[0]}</span><span>${cols[1]}</span><span>✓</span></div>${e.sets.map((s,si)=>setRow(e,s,ei,si)).join('')}<div class="exercise-tools"><button class="add-set" data-e="${ei}">＋ Seria</button><button class="copy-set" data-e="${ei}">⧉ Kopiuj</button><button class="toggle-warmup" data-e="${ei}">W Rozgrz.</button><button class="edit-exercise" data-e="${ei}">⚙ Ustaw.</button></div></article>`}
function setRow(e,s,ei,si){let fields;if(e.type==='reps'){const load=e.loadMode==='none'&&e.equipment!=='band'?'<span class="na">—</span>':`<input data-e="${ei}" data-s="${si}" data-f="kg" type="number" inputmode="decimal" value="${s.kg||0}">`;fields=`${load}<input data-e="${ei}" data-s="${si}" data-f="reps" type="number" inputmode="numeric" value="${s.reps||0}">`}else if(e.type==='time')fields=`<input data-e="${ei}" data-s="${si}" data-f="seconds" type="number" inputmode="numeric" value="${s.seconds||30}"><span class="na">—</span>`;else fields=`<input data-e="${ei}" data-s="${si}" data-f="steps" type="number" inputmode="numeric" value="${s.steps||20}"><span class="na">—</span>`;return`<div class="set-row compact ${s.done?'done':''} ${s.warmup?'warmup':''}"><b>${s.warmup?'W':si+1}</b>${fields}<button class="toggle-set" data-e="${ei}" data-s="${si}">${s.done?'✓':'○'}</button></div>`}
function syncActiveInputs(){document.querySelectorAll('.set-row input').forEach(el=>{const s=active?.ex[+el.dataset.e]?.sets[+el.dataset.s];if(s)s[el.dataset.f]=+el.value})}
function bindWorkout(){document.querySelector('#quit').onclick=()=>{if(confirm('Zakończyć bez zapisywania?')){clearInterval(timerId);clearDraft();active=null;view=null;render()}};document.querySelector('#finish-workout').onclick=()=>{syncActiveInputs();view='finish';clearInterval(timerId);persistDraft();finishPage()};document.querySelectorAll('.set-row input').forEach(el=>el.onchange=()=>{const s=active.ex[+el.dataset.e].sets[+el.dataset.s];s[el.dataset.f]=+el.value;persistDraft()});document.querySelectorAll('.toggle-set').forEach(b=>b.onclick=()=>{syncActiveInputs();const e=active.ex[+b.dataset.e],s=e.sets[+b.dataset.s];s.done=!s.done;if(s.done){checkRecord(e,s);startRest(e.rest||60)}persistDraft();workout()});document.querySelectorAll('.add-set,.copy-set').forEach(b=>b.onclick=()=>{syncActiveInputs();const e=active.ex[+b.dataset.e],last=e.sets.at(-1)||{reps:10,kg:0};e.sets.push({...last,done:false,warmup:false});persistDraft();workout()});document.querySelectorAll('.toggle-warmup').forEach(b=>b.onclick=()=>{const e=active.ex[+b.dataset.e];e.sets.push({reps:10,kg:0,done:false,warmup:true,seconds:30,steps:20});persistDraft();workout()});document.querySelectorAll('.edit-exercise').forEach(b=>b.onclick=()=>editExerciseSettings(+b.dataset.e));document.querySelectorAll('.remove-active').forEach(b=>b.onclick=()=>{if(confirm('Usunąć ćwiczenie z treningu?')){active.ex.splice(+b.dataset.e,1);persistDraft();workout()}});document.querySelectorAll('.exercise-history').forEach(b=>b.onclick=()=>{syncActiveInputs();view='exercise:'+encodeURIComponent(b.dataset.name);tab='history';render()});document.querySelector('#add-active-ex').onclick=()=>{syncActiveInputs();pickerFor='active';workout()};bindPicker();renderRest()}
function editExerciseSettings(i){syncActiveInputs();const e=normalizeExercise(active.ex[i]);document.body.insertAdjacentHTML('beforeend',`<div class="overlay exercise-settings-layer"><div class="modal exercise-settings"><div class="modal-head"><div><small>USTAWIENIA ĆWICZENIA</small><h2>${esc(e.name)}</h2></div><button id="close-ex-settings">×</button></div><div class="settings-grid"><label>Sprzęt<select id="es-equipment">${[['dumbbells','Hantle'],['barbell','Sztanga'],['kettlebell','Kettlebell'],['band','Taśma oporowa'],['bodyweight','Masa ciała'],['other','Inne']].map(([v,l])=>`<option value="${v}" ${e.equipment===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Sposób wpisywania ciężaru<select id="es-load"><option value="per_item" ${e.loadMode==='per_item'?'selected':''}>Ciężar jednego hantla</option><option value="total" ${e.loadMode==='total'?'selected':''}>Ciężar całkowity</option><option value="none" ${e.loadMode==='none'?'selected':''}>Bez objętości w kg</option></select></label><label>Liczba hantli / elementów<select id="es-count"><option value="1" ${+e.implementCount===1?'selected':''}>1</option><option value="2" ${+e.implementCount===2?'selected':''}>2</option></select></label><label>Sposób wykonywania<select id="es-sides"><option value="together" ${e.sideMode==='together'?'selected':''}>Obie strony jednocześnie</option><option value="per_side" ${e.sideMode==='per_side'?'selected':''}>Osobno — wynik na stronę</option><option value="alternating_total" ${e.sideMode==='alternating_total'?'selected':''}>Naprzemiennie — wynik łącznie</option></select></label><label>Czas przerwy<input id="es-rest" type="number" value="${e.rest||60}"><span>sek.</span></label><label class="full">Notatka<textarea id="es-note">${esc(e.note||'')}</textarea></label></div><p class="settings-hint">Dla dwóch hantli wpisuj wagę jednego. Dla sztangi wpisuj cały ciężar razem z gryfem i talerzami. Przy ćwiczeniu „na stronę” jeden wiersz obejmuje lewą i prawą stronę.</p><button id="save-ex-settings" class="primary wide">Zapisz ustawienia</button></div></div>`);const close=()=>document.querySelector('.exercise-settings-layer')?.remove();document.querySelector('#close-ex-settings').onclick=close;document.querySelector('#save-ex-settings').onclick=()=>{e.equipment=document.querySelector('#es-equipment').value;e.loadMode=document.querySelector('#es-load').value;e.implementCount=+document.querySelector('#es-count').value;e.sideMode=document.querySelector('#es-sides').value;e.rest=Math.max(0,+document.querySelector('#es-rest').value||0);e.note=document.querySelector('#es-note').value;if(e.equipment==='barbell')e.loadMode='total';if(['band','bodyweight'].includes(e.equipment))e.loadMode='none';exerciseProfiles[e.name]={equipment:e.equipment,loadMode:e.loadMode,implementCount:e.implementCount,sideMode:e.sideMode};plans.forEach(p=>p.ex.filter(x=>x.name===e.name).forEach(x=>Object.assign(x,exerciseProfiles[e.name])));save();persistDraft();close();workout()}}
function previousBest(name){let kg=0,reps=0;logs.forEach(l=>{const e=l.ex.find(x=>x.name===name);e?.sets.forEach(s=>{if(+s.kg>kg||(+s.kg===kg&&+s.reps>reps)){kg=+s.kg;reps=+s.reps}})});return{kg,reps}}
function checkRecord(e,s){if(e.type!=='reps')return;const b=previousBest(e.name);if(+s.kg>b.kg||(+s.kg===b.kg&&+s.reps>b.reps))toast(`Nowy rekord: ${e.name} — ${s.kg} ${loadUnit(e)} × ${s.reps}${e.sideMode==='per_side'?'/str.':''}`)}
function metricCells(e,s){normalizeExercise(e);if(e.type==='time')return`<span>${s.seconds||0} sek.</span><span>czas</span><span>${e.sideMode==='per_side'?'na stronę':'łącznie'}</span>`;if(e.type==='steps')return`<span>${s.steps||0}</span><span>kroków</span><span>${e.sideMode==='per_side'?'na stronę':'łącznie'}</span>`;const load=e.equipment==='band'?`${s.kg||0} oporu`:e.loadMode==='none'?'bez ciężaru':`${s.kg||0} ${loadUnit(e)}`;return`<span>${load}</span><span>${s.reps||0} powt.</span><span>${e.sideMode==='per_side'?'na stronę':e.sideMode==='alternating_total'?'łącznie':'jednocześnie'}</span>`}
function logDetail(id){const l=logs.find(x=>x.id===id);if(!l){view=null;return historyPage()}if(editLogId===id)return editLog(l);app.innerHTML=`<section><div class="detail-actions"><button id="back-history" class="back">← Historia</button><span><button id="edit-log">Edytuj</button><button id="delete-log">Usuń</button></span></div><label>${new Date(l.date).toLocaleDateString('pl',{weekday:'long',day:'numeric',month:'long'})}</label><h1>${esc(l.name)}</h1><div class="summary-kpis"><div><small>CZAS</small><strong>${l.minutes||0} min</strong></div><div><small>OBJĘTOŚĆ ZEWN.</small><strong>${volume(l)} kg</strong></div><div><small>KCAL</small><strong>${l.kcal||'—'}</strong></div></div>${l.notes?`<div class="session-note">${esc(l.notes)}</div>`:''}<div class="detail-list">${l.ex.map(e=>{normalizeExercise(e);return`<article><button class="open-exercise" data-name="${esc(e.name)}"><div><i>${muscleIcon(e.group)}</i><span><h2>${esc(e.name)} ›</h2><small>${esc(configSummary(e))}</small></span></div></button>${e.sets.filter(s=>s.done!==false).map((s,i)=>`<p><b>${s.warmup?'W':i+1}</b>${metricCells(e,s)}</p>`).join('')}</article>`}).join('')}</div></section>`;document.querySelector('#back-history').onclick=()=>{view=null;render()};document.querySelector('#edit-log').onclick=()=>{editLogId=id;render()};document.querySelector('#delete-log').onclick=()=>{if(confirm('Trwale usunąć ten trening?')){logs=logs.filter(x=>x.id!==id);save();view=null;render()}};document.querySelectorAll('.open-exercise').forEach(b=>b.onclick=()=>{view='exercise:'+encodeURIComponent(b.dataset.name);render()})}
function exerciseDetail(name){const entries=logs.flatMap(l=>{const e=l.ex.find(x=>x.name===name);return e?[{date:l.date,e:normalizeExercise(e)}]:[]}),best=Math.max(0,...entries.flatMap(x=>x.e.sets.map(s=>Number(s.kg)||0))),maxVol=Math.max(0,...entries.map(x=>volume({ex:[x.e]}))),unit=entries[0]?loadUnit(entries[0].e):'kg';app.innerHTML=`<section><button id="back-exercise" class="back">← Historia</button><label>HISTORIA ĆWICZENIA</label><h1>${esc(name)}</h1><div class="summary-kpis"><div><small>WYKONANIA</small><strong>${entries.length}</strong></div><div><small>NAJWIĘKSZY CIĘŻAR</small><strong>${best} ${unit}</strong></div><div><small>MAX OBJĘTOŚĆ</small><strong>${maxVol} kg</strong></div></div><div class="exercise-trend">${entries.slice(0,10).reverse().map(x=>`<i style="height:${20+(volume({ex:[x.e]})/Math.max(maxVol,1))*100}px"><b>${volume({ex:[x.e]})}</b><small>${new Date(x.date).toLocaleDateString('pl',{day:'numeric',month:'short'})}</small></i>`).join('')}</div><div class="exercise-entries">${entries.map(x=>`<article><small>${new Date(x.date).toLocaleDateString('pl',{weekday:'short',day:'numeric',month:'long'})}</small>${x.e.sets.filter(s=>s.done!==false).map((s,i)=>`<p><b>${i+1}</b>${metricCells(x.e,s)}</p>`).join('')}</article>`).join('')||'<p>Brak zapisów.</p>'}</div></section>`;document.querySelector('#back-exercise').onclick=()=>{view=null;render()}}
function exportJSON(){download(`treningi-backup-${localDay()}.json`,JSON.stringify({version:4,exportedAt:new Date().toISOString(),plans,logs,weights,favorites,recentExercises,ownedGear,exerciseProfiles},null,2),'application/json')}
function exportCSV(){const rows=[['data','trening','ćwiczenie','seria','rodzaj','sprzęt','sposób ciężaru','liczba elementów','praca stron','kg','powtórzenia','sekundy','kroki','objętość zewnętrzna','kcal','tętno']];logs.forEach(l=>l.ex.forEach(e=>{normalizeExercise(e);e.sets.forEach((s,i)=>rows.push([localDay(new Date(l.date)),l.name,e.name,i+1,e.type||'reps',equipmentName(e.equipment),e.loadMode,e.implementCount,e.sideMode,s.kg||'',s.reps||'',s.seconds||'',s.steps||'',setVolume(e,s),l.kcal||'',l.bpm||'']))}));download(`treningi-${localDay()}.csv`,rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(';')).join('\n'),'text/csv;charset=utf-8')}
function importJSON(ev){const f=ev.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!d.logs||!d.plans)throw Error();if(confirm(`Import zastąpi obecne dane (${logs.length} treningów). Kontynuować?`)){plans=d.plans;logs=d.logs;weights=d.weights||[];favorites=d.favorites||[];recentExercises=d.recentExercises||[];ownedGear=d.ownedGear||ownedGear;exerciseProfiles=d.exerciseProfiles||{};[...plans,...logs].forEach(p=>(p.ex||[]).forEach(normalizeExercise));save();render()}}catch{alert('Nie udało się odczytać kopii zapasowej.')}};r.readAsText(f)}
function muscleIcon(g){return({Nogi:'◒',Pośladki:'◉',Plecy:'↟',Klatka:'◇',Barki:'△',Ramiona:'⌁',Core:'◎',Kondycja:'ϟ',Mobilność:'∞',Rozciąganie:'⌇',Własne:'✦'}[g]||'◆')}
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
save();render();
